create table app_user (points float(53) not null, two_factor_enabled boolean, id bigint generated by default as identity, api_token varchar(64) unique, email varchar(255) not null unique, encrypted_keys TEXT, keys TEXT, password varchar(255), two_factor_email varchar(255), primary key (id));create table categories (id bigint generated by default as identity, name varchar(255) not null unique, primary key (id));
create table chat (favorite boolean not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, total_size bigint not null, user_id bigint not null, uuid uuid not null unique, primary key (id));
create table file_element (id bigint generated by default as identity, project_id bigint not null, user_id bigint not null, name varchar(255), content TEXT, primary key (id));
create table file_element_pages (file_element_id bigint not null, page_content varchar(255));
create table hosted_nodes (allow_public_use boolean not null, points_per1k_input float(53) not null, points_per1k_output float(53) not null, last_heartbeat timestamp(6) with time zone, owner_id bigint not null, total_requests bigint not null, total_tokens bigint not null, id uuid not null, auth_token varchar(255) not null unique, client_version varchar(255), model_family varchar(255), model_name varchar(255), node_name varchar(255), public_ip varchar(255), status varchar(255) check ((status in ('OFFLINE','ONLINE','BUSY','ERROR'))), primary key (id));
create table message (cache boolean not null, chat_id bigint not null, created_at timestamp(6) with time zone, end_time bigint, id bigint generated by default as identity, start bigint not null, uuid uuid unique, reasoning TEXT, role varchar(255), string_content TEXT, text TEXT, tool_call_id varchar(255), tool_calls_json TEXT, tool_name varchar(255), primary key (id));
create table message_documents (message_id bigint not null, document_id bigint, documents TEXT);
create table message_images (message_id bigint not null, image_url varchar(255));
create table model (global boolean not null, points_per_input float(53) not null, points_per_output float(53) not null, id bigint generated by default as identity, user_id bigint, name varchar(255), provider varchar(255), provider_strategy varchar(255) check ((provider_strategy in ('OPENAI','ANTHROPIC','DEFAULT','GEMINI','OPENROUTER','NVIDIA'))), text varchar(255), type varchar(255), url varchar(255), uuid varchar(255) unique, primary key (id));
create table post_image (display_order integer not null, id bigint generated by default as identity, size bigint not null, uploaded_at timestamp(6) with time zone not null, content_type varchar(255) not null, file_name varchar(255) not null, file_path varchar(255) not null, primary key (id));
create table posts (category_id bigint, created_at timestamp(6) not null, id bigint generated by default as identity, parent_id bigint, thumbnail_id bigint, updated_at timestamp(6), short_description varchar(500), content varchar(10000) not null, lang varchar(255) not null, slug varchar(255) not null unique, title varchar(255) not null, primary key (id));
create table project (id bigint generated by default as identity, user_id bigint not null, name varchar(255), primary key (id));
create table reset_token (is_used boolean not null, creation_time timestamp(6) not null, id bigint generated by default as identity, user_id bigint not null, token varchar(255) not null unique, user_login varchar(255), primary key (id));
create table shared_key (usage_count integer not null, working boolean not null, blocked_until timestamp(6), id bigint generated by default as identity, owner_id bigint, key_value varchar(255), provider varchar(255), primary key (id));
create table user_file (id bigint generated by default as identity, project_id bigint, size bigint not null, uploaded_at timestamp(6) with time zone not null, user_id bigint not null, base64_path varchar(255), content_type varchar(255) not null, file_name varchar(255) not null, stored_path varchar(255) not null, primary key (id));
create table user_roles (user_id bigint not null, role varchar(255) check ((role in ('USER','ADMIN'))));
create table audit_log (id bigint generated by default as identity, timestamp timestamp(6), user_id bigint, action varchar(255) check ((action in ('LOGIN_SUCCESS','EXCEPTION','LOGIN_FAILURE','LOGOUT','PASSWORD_CHANGE','PASSWORD_RESET_REQUEST','PASSWORD_RESET_CONFIRM','TWOFA_VERIFY','TWOFA_ENABLE','TWOFA_DISABLE','ROLE_UPDATE','USER_CREATE','USER_DELETE','SHARED_KEY_GENERATE','SHARED_KEY_DELETE','BLOG_CREATE','BLOG_UPDATE','BLOG_DELETE','MEDIA_UPLOAD','MEDIA_DELETE','DATA_EXPORT','SENSITIVE_READ','ADMIN_ACTION','RATE_LIMIT_EXCEEDED'))), details varchar(255), ip_address varchar(255), payload TEXT, result varchar(255) check ((result in ('SUCCESS','FAILURE'))), session_id varchar(255), target varchar(255), user_agent varchar(255), username varchar(255), primary key (id));
create index idx_audit_user on audit_log (user_id);
create index idx_audit_action on audit_log (action);
create index idx_audit_timestamp on audit_log (timestamp);
create table migration_flag (id bigint generated by default as identity, executed boolean, executed_at timestamp(6), name varchar(255), primary key (id));
